#Requires -Version 5.1
# fix-build-suspense-sharp.ps1
# Error 1: useSearchParams() debe estar en Suspense boundary
#   FIX: extraído a componente EditFromURL envuelto en <Suspense>
# Error 2: Module not found 'sharp' (warning Webpack)
#   FIX: require('sharp') lazy dentro de la funcion, no en modulo

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix build Suspense + sharp" -ForegroundColor Cyan

Write-Host "  -> src\app\maestros\recursos-humanos\page.tsx" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), $bytes)
Write-Host "  OK: 21 KB" -ForegroundColor Green

Write-Host "  -> src\app\api\partes\email\route.ts" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\api\partes\email\route.ts"), $bytes)
Write-Host "  OK: 7 KB" -ForegroundColor Green

Write-Host "  -> src\lib\pdf\generatePartePdf.ts" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\lib\pdf\generatePartePdf.ts"), $bytes)
Write-Host "  OK: 11 KB" -ForegroundColor Green

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("<Suspense")) { Write-Host "  OK: Suspense boundary" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("EditFromURL")) { Write-Host "  OK: EditFromURL componente" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "fix: Suspense para useSearchParams + sharp lazy"'
Write-Host "  git push"
